PENAL_QUESTIONS.push({"id":"fcc-penal-251375","sourceQuestionId":"251375","t":"pen-m06","moduleId":"pen-m06","q":"No caso de condenação igual ou inferior a quatro anos, admissível a adoção do regime","o":["fechado, ainda que fixada a pena-base no mínimo legal.","aberto, se favoráveis as circunstâncias judiciais, ainda que reincidente o agente.","aberto, se reincidente o agente e desfavoráveis as circunstâncias judiciais.","semiaberto, se reincidente o agente e favoráveis as circunstâncias judiciais.","semiaberto, se reincidente o agente e desfavoráveis as circunstâncias judiciais."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - DP CE/DPE CE/2014 • TEC 251375","source":"FCC - DP CE/DPE CE/2014","subject":"Direito Penal - Penas Privativas de Liberdade: Espécies, Regimes e Progressão (arts. 32 a 42 e 53 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/251375","year":2014,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-119837","sourceQuestionId":"119837","t":"pen-m06","moduleId":"pen-m06","q":"A pena privativa de liberdade é","o":["inicialmente cumprida em regime de isolamento celular, pese progressiva.","de reclusão, detenção ou prisão simples, com caráter progressivo.","cumprida em regime fechado ou semiaberto, não no aberto.","cumprida em regime semiaberto ou aberto, não no fechado.","cumprida em regime fechado, não no semiaberto ou aberto."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - NeR (TJ PE)/TJ PE/Provimento/2013 • TEC 119837","source":"FCC - NeR (TJ PE)/TJ PE/Provimento/2013","subject":"Direito Penal - Penas Privativas de Liberdade: Espécies, Regimes e Progressão (arts. 32 a 42 e 53 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/119837","year":2013,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-119839","sourceQuestionId":"119839","t":"pen-m06","moduleId":"pen-m06","q":"O trabalho do preso definitivamente condenado é","o":["gratuito nos três regimes prisionais.","obrigatório no fechado e facultativo nos demais regimes prisionais.","remunerado e assistido pela Previdência Social.","gratuito, porém excepcionalmente remunerado.","remunerado, porém excepcionalmente gratuito."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - NeR (TJ PE)/TJ PE/Provimento/2013 • TEC 119839","source":"FCC - NeR (TJ PE)/TJ PE/Provimento/2013","subject":"Direito Penal - Penas Privativas de Liberdade: Espécies, Regimes e Progressão (arts. 32 a 42 e 53 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/119839","year":2013,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-68709","sourceQuestionId":"68709","t":"pen-m06","moduleId":"pen-m06","q":"As circunstâncias agravantes","o":["podem elevar a pena acima do máximo previsto em lei para o crime, do mesmo modo que as causas de aumento.","não incidem nos crimes culposos, salvo a reincidência.","serão consideradas na fixação da pena-base.","sempre preponderam sobre as circunstâncias atenuantes, no caso de concurso entre umas e outras.","não incidem quando também qualificarem o crime, mas podem ser aplicadas se elementares da infração."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - JE TJGO/TJ GO/2012 • TEC 68709","source":"FCC - JE TJGO/TJ GO/2012","subject":"Direito Penal - Penas Privativas de Liberdade: Espécies, Regimes e Progressão (arts. 32 a 42 e 53 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/68709","year":2012,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-120709","sourceQuestionId":"120709","t":"pen-m06","moduleId":"pen-m06","q":"Lucius foi condenado, pelo mesmo crime, no Brasil, à pena de três anos de reclusão e, no estrangeiro, à pena de um ano de reclusão. Cumpriu integralmente a pena imposta no outro país. Nesse caso, a pena imposta no Brasil","o":["será reduzida de um terço a um sexto.","será atenuada, a critério do juiz.","será reduzida em metade.","não sofrerá qualquer redução.","será reduzida a dois anos."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - AJ TRF2/TRF 2/Judiciária/Oficial de Justiça Avaliador Federal/2012 • TEC 120709","source":"FCC - AJ TRF2/TRF 2/Judiciária/Oficial de Justiça Avaliador Federal/2012","subject":"Direito Penal - Penas Privativas de Liberdade: Espécies, Regimes e Progressão (arts. 32 a 42 e 53 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/120709","year":2012,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1992292","sourceQuestionId":"1992292","t":"pen-m06","moduleId":"pen-m06","q":"Nos crimes praticados com violação do dever para com a administração pública, cabível a perda de cargo, função pública ou mandato eletivo quando aplicada pena privativa de liberdade por tempo igual ou superior a","o":["04 (quatro) anos.","01 (um) ano.","06 (seis) meses.","02 (dois) anos.","03 (três) anos."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - Prom Jus (MPE AL)/MPE AL/1ª Entrância/2012 • TEC 1992292","source":"FCC - Prom Jus (MPE AL)/MPE AL/1ª Entrância/2012","subject":"Direito Penal - Penas Privativas de Liberdade: Espécies, Regimes e Progressão (arts. 32 a 42 e 53 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1992292","year":2012,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-87019","sourceQuestionId":"87019","t":"pen-m06","moduleId":"pen-m06","q":"Sobre as penas privativas de liberdade previstas no Código Penal brasileiro, é correto afirmar:","o":["No regime fechado, se o condenado trabalhar durante o dia ficará dispensado do isolamento noturno.","Considera-se regime semi-aberto a execução da pena em casa de albergado ou estabelecimento adequado.","A pena de reclusão deve ser cumprida em regime fechado, semi-aberto ou aberto.","No regime fechado é proibido o trabalho externo em qualquer serviço.","No regime semi-aberto o condenado deverá trabalhar, frequentar curso ou exercer outra atividade autorizada, fora do estabelecimento e sem vigilância, permanecendo recolhido durante o período noturno e nos dias de folga."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - AJ TRE TO/TRE TO/Administrativa/\"Sem Especialidade\"/2011 • TEC 87019","source":"FCC - AJ TRE TO/TRE TO/Administrativa/\"Sem Especialidade\"/2011","subject":"Direito Penal - Penas Privativas de Liberdade: Espécies, Regimes e Progressão (arts. 32 a 42 e 53 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/87019","year":2011,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3937797","sourceQuestionId":"3937797","t":"pen-m06","moduleId":"pen-m06","q":"A reincidência","o":["não específica admite o reconhecimento do furto privilegiado, desde que a coisa furtada seja de pequeno valor e a medida seja socialmente recomendável.","específica impede a concessão de livramento condicional pelo magistrado na sentença condenatória pelo crime de tráfico de drogas.","impede o reconhecimento do princípio da insignificância e a fixação de regime aberto, conforme entendimento do Supremo Tribunal Federal.","específica ou genérica aumenta em terça parte o prazo prescricional da pretensão punitiva do Estado.","não específica, quando socialmente recomendável, possibilita a substituição da pena privativa de liberdade por restritivas de direitos."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - DP MA/DPE MA/2026 • TEC 3937797","source":"FCC - DP MA/DPE MA/2026","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3937797","year":2026,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3937823","sourceQuestionId":"3937823","t":"pen-m06","moduleId":"pen-m06","q":"Acerca das penas restritivas de direitos, é correto afirmar:","o":["A perda de bens e valores em favor do Fundo Penitenciário Nacional terá como teto o montante do prejuízo causado à vítima, sendo irrelevante o provento obtido pelo agente ou por terceiro em consequência do crime.","A prestação pecuniária paga à vítima será deduzida de eventual condenação em ação de reparação civil, desde que os beneficiários sejam coincidentes, podendo, desde que haja aceitação do beneficiário, consistir em prestação de natureza diversa do pagamento em dinheiro.","Na condenação igual ou inferior a um ano, a substituição somente poderá ser feita por uma pena restritiva de direitos, sendo vedada a substituição exclusivamente por multa.","A execução provisória de penas restritivas de direitos como a limitação de final de semana deve observar as condições pessoais do agente, como residência e trabalho fixos.","Descumprida injustificadamente a pena restritiva de direitos, esta se converte em privativa de liberdade, deduzindo-se o tempo já cumprido, sem qualquer limitação quanto ao saldo mínimo remanescente a cumprir."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - DP MA/DPE MA/2026 • TEC 3937823","source":"FCC - DP MA/DPE MA/2026","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3937823","year":2026,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3563058","sourceQuestionId":"3563058","t":"pen-m06","moduleId":"pen-m06","q":"Considere os seguintes casos hipotéticos, em que houve aplicação de penas em processos criminais: I. José, primário, foi condenado a um ano de reclusão por ordenar operação de crédito externo, sem prévia autorização legislativa (art. 359-A, caput, do Código Penal), tendo sido sua pena privativa de liberdade substituída por prestação de serviços à comunidade. II. Maria, reincidente específica, foi condenada a dois anos de reclusão por ordenar despesa não autorizada por lei (art. 359-D, do Código Penal), tendo sido sua pena privativa de liberdade substituída por prestação de serviços à comunidade e dez dias-multa, o unitário no mínimo legal. III. João, primário, foi condenado a três anos de reclusão e dez dias-multa, o unitário no piso legal, por restringir, com emprego de violência física, o exercício de direitos políticos de deputado estadual em razão de sua raça (art. 359-P, do Código Penal), tendo sido sua pena privativa de liberdade substituída por prestação pecuniária e interdição temporária de direitos. IV. Tício, reincidente pela prática de crime de receptação, foi condenado a um ano e dois meses de reclusão, além de onze dias-multa, o unitário no piso, pela prática de crime de falsidade ideológica em documento público (art. 299, caput, do Código Penal), tendo sido sua pena privativa de liberdade substituída por prestação de serviços à comunidade e prestação pecuniária, justificando o magistrado que a reincidência não é específica e que em face da condenação anterior a medida se mostrava socialmente recomendável. Nos termos do Código Penal, as penas foram corretamente aplicadas no(s) processo(s) de","o":["José e João, apenas.","José, apenas.","José e Tício, apenas.","José, Maria e Tício, apenas.","José, Maria, João e Tício."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - AFFE (SEFAZ PI)/SEFAZ PI/Tecnologia da Informação/2025 • TEC 3563058","source":"FCC - AFFE (SEFAZ PI)/SEFAZ PI/Tecnologia da Informação/2025","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3563058","year":2025,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3233115","sourceQuestionId":"3233115","t":"pen-m06","moduleId":"pen-m06","q":"Considere os seguintes casos hipotéticos: O Prefeito Maurício ordenou operação de crédito externo, sem prévia autorização legislativa, e está sendo processado pelo crime de contratação de operação de crédito, previsto no artigo 359-A, do Código Penal, e após o trâmite regular do processo Maurício é condenado pelo Magistrado competente a cumprir pena de reclusão de 1 ano. Marilda ingressou no território brasileiro importando mercadorias proibidas do Paraguai e foi presa em flagrante. Ela está sendo processada por crime, em tese, de contrabando, previsto no artigo 334-A, do Código Penal, e após o trâmite regular do processo Marilda é condenada pelo Magistrado competente a cumprir pena de reclusão de 3 anos. Rodolfo, administrador público, realiza a contratação sem licitação de uma empresa para execução de obra pública e é denunciado e processado pelo crime de contratação direta ilegal, previsto no artigo 337-E, do Código Penal. Ao final da regular instrução do feito Rodolfo é condenado pelo Magistrado competente a cumprir pena de reclusão de 5 anos e multa. Nos termos preconizados pelo Código Penal, considerando que todas as pessoas mencionadas não são reincidentes em crimes dolosos, a culpabilidade, os antecedentes, a conduta social e a personalidade dos agentes, bem como os motivos e as circunstâncias indicarem que o benefício é suficiente, o Magistrado competente poderá substituir em sentença as penas privativas de liberdade fixadas por penas restritivas de direitos para:","o":["Marilda e Rodolfo.","Marilda e Rodolfo, apenas.","Maurício, apenas.","Maurício e Marilda, apenas.","Marilda, apenas."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - Ana Gov (SEAD PI)/SEAD PI/Planejamento e Orçamento/2024 • TEC 3233115","source":"FCC - Ana Gov (SEAD PI)/SEAD PI/Planejamento e Orçamento/2024","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3233115","year":2024,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1994835","sourceQuestionId":"1994835","t":"pen-m06","moduleId":"pen-m06","q":"Maria, em decorrência da prática de crime doloso, foi condenada ao cumprimento de pena privativa de liberdade, substituída por restritiva de direitos em processo em que se deu o trânsito em julgado. Dentre as hipóteses abaixo, são penas de interdição temporária de direitos: I. Proibição do exercício de cargo, função ou atividade pública. II. Limitação de fim de semana. III. Proibição de inscrever-se em concurso, avaliação ou exame públicos. IV. Suspensão de autorização ou de habilitação para dirigir veículo. Está correto o que se afirma APENAS em","o":["I, III e IV.","II, III e IV.","I, II e III.","I, II e IV.","III e IV."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - Prom Jus (MPE PE)/MPE PE/2022 • TEC 1994835","source":"FCC - Prom Jus (MPE PE)/MPE PE/2022","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1994835","year":2022,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2211970","sourceQuestionId":"2211970","t":"pen-m06","moduleId":"pen-m06","q":"São espécies de penas restritivas de direitos:","o":["a prestação pecuniária e o recolhimento domiciliar noturno.","a prestação de serviços à comunidade e a suspensão do exercício de função pública.","a reparação do dano causado e a prestação pecuniária.","a perda de bens e valores e a multa.","a interdição temporária de direitos e a prestação de serviços a entidades públicas."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - DP (DPE AP)/DPE AP/2022 • TEC 2211970","source":"FCC - DP (DPE AP)/DPE AP/2022","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2211970","year":2022,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1684630","sourceQuestionId":"1684630","t":"pen-m06","moduleId":"pen-m06","q":"Sobre as penas restritivas de direitos, é correto afirmar:","o":["O descumprimento prévio de acordo de não persecução penal impossibilita a substituição da pena privativa de liberdade por restritivas de direitos na sentença.","A prestação de serviços à comunidade ou a entidades públicas é aplicável às condenações inferiores a seis meses de privação da liberdade.","Se o crime for praticado com violência ou ameaça à pessoa, o juiz poderá aplicar a substituição da pena privativa de liberdade por restritiva de direitos, desde que a medida seja socialmente recomendável.","A pena restritiva de direitos que substitui pena privativa de liberdade superior a um ano pode ser cumprida em menor tempo, nunca inferior à metade da pena fixada.","A limitação de fim de semana restringe-se aos crimes punidos com detenção."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - DP BA/DPE BA/2021 • TEC 1684630","source":"FCC - DP BA/DPE BA/2021","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1684630","year":2021,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1736885","sourceQuestionId":"1736885","t":"pen-m06","moduleId":"pen-m06","q":"No que se refere às penas restritivas de direitos,","o":["a correspondente execução independe do trânsito em julgado da condenação, mas poderá o juiz, motivadamente, alterar a forma de cumprimento da prestação de serviços à comunidade, ajustando-a às condições pessoais do condenado.","o juiz poderá estabelecer condição especial para a concessão do regime aberto, sem prejuízo das gerais e obrigatórias, desde que não constitua pena substitutiva.","o descumprimento injustificado da restrição, imposta em sentença condenatória ou acordada em sede de transação penal, conduz à conversão para pena privativa de liberdade.","a prestação de serviços à comunidade é aplicável a qualquer condenação não superior a quatro anos, facultado ao condenado cumpri-la em menor tempo, nunca inferior à metade da pena privativa de liberdade, se a pena substituída foi superior a um ano.","a prestação pecuniária, se não paga, não poderá ser convertida em pena privativa de liberdade e será considerada dívida de valor, aplicando-se as normas da legislação relativa à dívida ativa da Fazenda Pública."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - JE TJGO/TJ GO/2021 • TEC 1736885","source":"FCC - JE TJGO/TJ GO/2021","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1736885","year":2021,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1769152","sourceQuestionId":"1769152","t":"pen-m06","moduleId":"pen-m06","q":"As penas restritivas de direitos","o":["são aplicáveis ao reincidente específico, desde que a medida seja socialmente recomendável.","substituem as penas privativas de liberdade quando estas não superam seis anos em caso de réu idoso.","prescrevem no mesmo prazo previsto para as penas privativas de liberdade que substituem.","de prestação de serviços à comunidade ou a entidades públicas são aplicáveis às condenações superiores a 1 (um) ano de privação de liberdade, desde que a pena seja de detenção.","deverão ser obrigatoriamente convertidas em pena privativa de liberdade se sobrevier nova condenação dessa espécie por outro crime."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - DP RR/DPE RR/2021 • TEC 1769152","source":"FCC - DP RR/DPE RR/2021","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1769152","year":2021,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-592144","sourceQuestionId":"592144","t":"pen-m06","moduleId":"pen-m06","q":"Os antecedentes criminais","o":["podem ser considerados negativamente na aplicação da pena com o registro de atos infracionais, vedando-se, contudo, para efeitos de reincidência.","podem aumentar a pena-base acima do mínimo legal com o registro decorrente da aceitação de transação penal pelo acusado.","podem ser verificados a partir da existência de ações penais em curso, mas não de inquéritos policiais na mesma condição.","podem ser considerados para fins de cabimento da substituição da pena privativa de liberdade por restritiva de direitos.","constituem circunstância agravante que incide com a regular certidão comprobatória de condenação anterior."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - DP AM/DPE AM/2018 • TEC 592144","source":"FCC - DP AM/DPE AM/2018","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/592144","year":2018,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-592152","sourceQuestionId":"592152","t":"pen-m06","moduleId":"pen-m06","q":"A pena restritiva de direitos","o":["pode substituir a privativa de liberdade em caso de reincidente em crime culposo, salvo se a pena for superior a quatro anos.","de limitação de fim de semana é vedada para crimes patrimoniais e contra a administração pública.","de prestação pecuniária é indisponível e por isso não pode consistir em prestação de outra natureza mesmo com concordância da vítima.","de prestação de serviço à comunidade pode ser cumprida em tempo menor do que a pena privativa de liberdade substituída, se esta for superior a um ano.","pode ser cumulada com medida de segurança na modalidade de tratamento ambulatorial, pois não implica em restrição da liberdade."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - DP AM/DPE AM/2018 • TEC 592152","source":"FCC - DP AM/DPE AM/2018","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/592152","year":2018,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-660228","sourceQuestionId":"660228","t":"pen-m06","moduleId":"pen-m06","q":"Em 2014, por conduta perpetrada em 2011, Ataulfo foi denunciado pela prática de lesão corporal simples (art. 129, caput, do CP). Em 2016, por conduta perpetrada em 2015, Ataulfo viu-se novamente denunciado, dessa vez pela prática de ameaça. Já em 2017, em razão de conduta praticada em 2016, Ataulfo foi condenado pela prática de furto qualificado pelo emprego de chave falsa, sendo-lhe aplicada uma pena privativa de liberdade de 04 anos de reclusão. Nesse caso,","o":["é possível substituir a pena privativa de liberdade aplicada por uma pena restritiva de direitos.","não é possível substituir a pena privativa de liberdade por restritivas de direitos, tendo em vista a reincidência.","não é possível substituir a pena privativa de liberdade por restritiva de direitos, tendo em vista a natureza do crime que ensejou a condenação (furto qualificado pelo emprego de chave falsa).","não é possível substituir a pena privativa de liberdade por restritivas de direitos, tendo em vista a extensão da pena aplicada.","é possível substituir a pena privativa de liberdade aplicada por uma pena restritiva de direitos e multa."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - DP RS/DPE RS/2018 • TEC 660228","source":"FCC - DP RS/DPE RS/2018","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/660228","year":2018,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-780327","sourceQuestionId":"780327","t":"pen-m06","moduleId":"pen-m06","q":"É espécie de pena de interdição temporária de direitos","o":["proibição de saída temporária no regime semiaberto.","proibição de frequentar determinados lugares.","obrigação de se desculpar com a vítima do delito.","prestação de serviços à comunidade.","suspensão do direito ao indulto."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - Ag Pen (IAPEN AP)/IAPEN AP/2018 • TEC 780327","source":"FCC - Ag Pen (IAPEN AP)/IAPEN AP/2018","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/780327","year":2018,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-780377","sourceQuestionId":"780377","t":"pen-m06","moduleId":"pen-m06","q":"São espécies de penas restritivas de direitos","o":["a prisão administrativa e limitação de fim de semana.","a multa e prestação de serviço à comunidade.","o regime aberto e remição.","a prestação pecuniária e interdição temporária de direitos.","o livramento condicional e comutação."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - Edu SP (IAPEN AP)/IAPEN AP/Nível Médio/2018 • TEC 780377","source":"FCC - Edu SP (IAPEN AP)/IAPEN AP/Nível Médio/2018","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/780377","year":2018,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-467237","sourceQuestionId":"467237","t":"pen-m06","moduleId":"pen-m06","q":"A pena de prestação de serviços à comunidade","o":["deve ser cumprida à razão de duas horas de tarefa por dia de condenação, fixadas de modo a não prejudicar a jornada de trabalho.","não é aplicável, em nenhuma hipótese, caso o condenado for reincidente.","não pode ser cumprida em menor tempo pelo condenado, se a condenação for superior a um ano.","aplica-se às condenações superiores a seis meses de privação de liberdade.","não substitui a pena privativa de liberdade."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - DP PR/DPE PR/2017 • TEC 467237","source":"FCC - DP PR/DPE PR/2017","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/467237","year":2017,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-396935","sourceQuestionId":"396935","t":"pen-m06","moduleId":"pen-m06","q":"Fica sujeito a trabalho em comum durante o período diurno, em colônia agrícola, industrial ou estabelecimento similar o condenado à pena","o":["de reclusão ou detenção, que cumpre pena em regime fechado.","restritiva de direitos de prestação de serviços à comunidade.","de reclusão ou detenção, que cumpre pena em regime semi-aberto.","restritiva de direitos de interdição temporária de direitos.","restritiva de direitos de prestação pecuniária e de perda de bens e valores."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - AFRM (Pref Teresina)/Pref Teresina/2016 • TEC 396935","source":"FCC - AFRM (Pref Teresina)/Pref Teresina/2016","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/396935","year":2016,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-315414","sourceQuestionId":"315414","t":"pen-m06","moduleId":"pen-m06","q":"Sobre as penas restritivas de direito é certo que","o":["se o condenado for reincidente o juiz não poderá substituir a pena privativa de liberdade por pena restritiva de direitos em caso de nova condenação.","no caso de prestação de serviços à comunidade ou entidades públicas se a pena substituída for superior a um ano, é facultado ao condenado cumprir a pena substitutiva em menor tempo, nunca inferior a 2/3 da pena privativa de liberdade fixada.","no caso de descumprimento injustificado da pena restritiva de direitos ela converte-se em privativa de liberdade e, no cálculo da pena privativa de liberdade a executar será deduzido o tempo cumprido da pena restritiva de direitos, respeitado o saldo mínimo de trinta dias de detenção ou reclusão.","se tratando de prestação pecuniária o valor pago pelo réu não será deduzido do montante de eventual condenação em ação de reparação civil, ainda que coincidentes os beneficiários.","a prestação de serviços à comunidade ou a entidades públicas é aplicável apenas às condenações superiores a um ano de privação da liberdade."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - AJ TRE AP/TRE AP/Administrativa/2015 • TEC 315414","source":"FCC - AJ TRE AP/TRE AP/Administrativa/2015","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/315414","year":2015,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-315579","sourceQuestionId":"315579","t":"pen-m06","moduleId":"pen-m06","q":"Tício, primário e de bons antecedentes, é denunciado e regularmente processado por crime de falsificação de documento público (artigo 297, do Código Penal). Após o encerramento da regular instrução do feito, Tício é condenado a cumprir pena de 3 anos e 6 meses de reclusão. Neste caso o Magistrado, presentes os demais requisitos legais,","o":["poderá substituir a pena privativa de liberdade por multa ou por uma pena restritiva de direitos.","não poderá substituir a pena privativa de liberdade por restritiva de direitos uma vez que a pena fixada impede o benefício.","poderá substituir a pena privativa de liberdade por uma pena restritiva de direitos e multa ou duas penas restritivas de direitos.","poderá substituir a pena privativa de liberdade apenas por duas penas restritivas de direitos diante da pena cominada.","poderá substituir a pena privativa de liberdade por três penas privativas de liberdade."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - AJ TRE SE/TRE SE/Administrativa/\"Sem Especialidade\"/2015 • TEC 315579","source":"FCC - AJ TRE SE/TRE SE/Administrativa/\"Sem Especialidade\"/2015","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/315579","year":2015,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-209588","sourceQuestionId":"209588","t":"pen-m06","moduleId":"pen-m06","q":"No tocante às penas restritivas de direitos,","o":["há conversão em privativa de liberdade quando ocorrer o descumprimento injustificado da restrição imposta, sem dedução do tempo cumprido da sanção substitutiva.","é possível a imposição de interdição temporária de direitos consistente em proibição de inscrever-se em concurso, avaliação ou exame públicos.","é admissível a fixação de pena substitutiva como condição especial ao regime aberto, conforme entendimento sumulado do Superior Tribunal de Justiça.","é obrigatória a conversão, se sobrevier condenação à pena privativa de liberdade.","a perda de bens e valores pertencentes ao condenado dar-se-á, preferencialmente, em favor da vítima ou de seus sucessores."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - JE TJCE/TJ CE/2014 • TEC 209588","source":"FCC - JE TJCE/TJ CE/2014","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/209588","year":2014,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-217105","sourceQuestionId":"217105","t":"pen-m06","moduleId":"pen-m06","q":"Para substituição da pena privativa de liberdade por pena restritiva de direitos impõe-se, de acordo com o Código Penal, que","o":["a pena originária seja de até 4 anos.","o réu seja primário em crime doloso.","a substituição seja socialmente recomendável.","o réu tenha bons antecedentes.","as circunstâncias judiciais indiquem a suficiência da substituição."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - DP PB/DPE PB/2014 • TEC 217105","source":"FCC - DP PB/DPE PB/2014","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/217105","year":2014,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-680988","sourceQuestionId":"680988","t":"pen-m06","moduleId":"pen-m06","q":"A pena de prestação de serviços à comunidade","o":["pode ser cumprida pelo condenado em menor tempo, se a pena substituída for superior a seis meses e não exceder a um ano.","pode ser aplicada independentemente do tempo de privação de liberdade a que condenado o acusado.","não pode ser imposta como condição do sursis por força de vedação legal.","não pode ser a única sanção substitutiva no caso de condenação igual ou inferior a um ano.","não pode ser fixada como condição especial ao regime aberto."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - Prom Jus (MPE PE)/MPE PE/2014 • TEC 680988","source":"FCC - Prom Jus (MPE PE)/MPE PE/2014","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/680988","year":2014,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-118103","sourceQuestionId":"118103","t":"pen-m06","moduleId":"pen-m06","q":"A reincidência","o":["sempre impede a substituição da pena privativa de liberdade por restritiva de direitos.","pode ser considerada como circunstância agravante e, simultaneamente, como circunstância judicial.","não influi no prazo da prescrição da pretensão punitiva.","obsta a suspensão condicional da pena, ainda que a condenação anterior tenha imposto tão somente a pena de multa.","fica excluída automaticamente pela reabilitação."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - DP AM/DPE AM/2013 • TEC 118103","source":"FCC - DP AM/DPE AM/2013","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/118103","year":2013,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-121268","sourceQuestionId":"121268","t":"pen-m06","moduleId":"pen-m06","q":"No tocante às penas restritivas de direitos, é correto afirmar que","o":["o teto da perda de bens ou valores é restrito ao montante do prejuízo causado.","obstam a concessão do sursis, se indicada ou cabível a substituição.","podem ser impostas no caso de condenação por crime culposo, se não reincidente o condenado.","a prestação de serviços à comunidade ou a entidades públicas somente é aplicável às condenações superiores a um ano de privação de liberdade.","a privativa de liberdade superior a um ano deve ser necessariamente substituída por duas restritivas de direitos."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - JE TJPE/TJ PE/2013 • TEC 121268","source":"FCC - JE TJPE/TJ PE/2013","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/121268","year":2013,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-609060","sourceQuestionId":"609060","t":"pen-m06","moduleId":"pen-m06","q":"A proibição de inscrever-se em concurso, avaliação ou exame públicos, de acordo com o Código Penal Brasileiro representa","o":["um efeito da pena privativa de liberdade, mesmo cumprida em regime aberto.","uma interdição temporária de direitos.","uma condição para suspensão condicional da pena.","um efeito da condenação.","uma condição do livramento condicional."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - Tec Min (MPE CE)/MPE CE/2013 • TEC 609060","source":"FCC - Tec Min (MPE CE)/MPE CE/2013","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/609060","year":2013,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-64235","sourceQuestionId":"64235","t":"pen-m06","moduleId":"pen-m06","q":"Considere as seguintes situações hipotéticas de cidadãos processados pela Justiça Pública: I. José, não reincidente, é condenado a cumprir pena de 04 anos de reclusão por crime de denunciação caluniosa e poderá iniciar o cumprimento da pena em regime aberto. II. Paulo é condenado a cumprir pena de 02 anos de reclusão por crime de coação no curso do processo, e tem sua pena privativa de liberdade substituída por uma pena restritiva de direitos e por multa. III. Murilo registra condenação anterior por crime de falso testemunho e está sendo processado por crime de peculato. Nesse caso, não poderá ter a sua pena privativa de liberdade substituída pela restritiva de direitos, por expressa vedação legal. De acordo com o Código Penal, está correto o que consta APENAS em","o":["I.","II.","III.","I e II.","II e III."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - AJ TRE SP/TRE SP/Judiciária/2012 • TEC 64235","source":"FCC - AJ TRE SP/TRE SP/Judiciária/2012","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/64235","year":2012,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-68707","sourceQuestionId":"68707","t":"pen-m06","moduleId":"pen-m06","q":"Em relação às penas restritivas de direitos, é correto afirmar que","o":["o juiz da execução penal, sobrevindo condenação a pena privativa de liberdade, por outro crime ou contravenção, decidirá sobre a conversão, podendo deixar de aplicá-la se for possível ao condenado cumprir a pena substitutiva anterior.","a prestação de serviços à comunidade terá a mesma duração da pena privativa de liberdade substituída e, se esta for superior a 1 (um) ano, poderá o condenado cumpri-la em menor tempo, nunca inferior a 1/3 (um terço) da sanção corporal fixada.","a prestação pecuniária consiste no pagamento em dinheiro à vítima, a seus dependentes ou a entidade pública ou privada com destinação social, de importância fixada pelo juiz, não inferior a 10 (dez) diasmulta nem superior a 360 (trezentos e sessenta) dias-multa. O valor pago será deduzido do montante de eventual condenação em ação de reparação civil, se coincidentes os beneficiários.","é incabível a pena substitutiva de interdição temporária de direitos, na modalidade de suspensão da habilitação para dirigir veículo, no caso de homicídio culposo na direção de veículo automotor.","é conversível em privativa de liberdade quando ocorrer o descumprimento injustificado da restrição imposta, sem dedução do tempo cumprido de pena substitutiva."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - JE TJGO/TJ GO/2012 • TEC 68707","source":"FCC - JE TJGO/TJ GO/2012","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/68707","year":2012,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-120539","sourceQuestionId":"120539","t":"pen-m06","moduleId":"pen-m06","q":"O fornecimento de cestas básicas a instituições de caridade inclui-se dentre as penas","o":["de multa.","privativas de liberdade.","restritivas de direitos.","de prisão simples.","acessórias."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - AJ TRF2/TRF 2/Judiciária/\"Sem Especialidade\"/2012 • TEC 120539","source":"FCC - AJ TRF2/TRF 2/Judiciária/\"Sem Especialidade\"/2012","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/120539","year":2012,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-377029","sourceQuestionId":"377029","t":"pen-m06","moduleId":"pen-m06","q":"Mauricio, primário e de bons antecedentes, é condenado a cumprir pena de 03 (três) anos e 08 (oito) meses de reclusão, em regime inicial semi aberto, por crime de corrupção ativa (artigo 333, do Código Penal). Neste caso, o Magistrado","o":["não poderá substituir a pena privativa de liberdade pela restritiva de direitos, tendo em vista que o Código Penal veda expressamente a concessão desse benefício ao crime cometido pelo réu Maurício, independentemente da quantidade da pena aplicada.","não poderá substituir a pena privativa de liberdade pela restritiva de direitos, tendo em vista a quantidade da pena imposta (superior a três anos).","poderá substituir a pena privativa de liberdade aplicada por três penas restritivas de direito.","poderá substituir a pena privativa de liberdade por uma pena restritiva de direitos ou multa.","poderá substituir a pena privativa de liberdade aplicada por uma pena restritiva de direitos e multa ou por duas penas restritivas de direito."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - AJ (TRE CE)/TRE CE/Administrativa/\"Sem Especialidade\"/2012 • TEC 377029","source":"FCC - AJ (TRE CE)/TRE CE/Administrativa/\"Sem Especialidade\"/2012","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/377029","year":2012,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-121478","sourceQuestionId":"121478","t":"pen-m06","moduleId":"pen-m06","q":"A pena de prestação pecuniária","o":["é sempre incabível para o condenado reincidente.","deve ser fixada em dias-multa.","só pode ser estabelecida em favor da vítima ou de seus dependentes.","é autônoma e, nos crimes culposos, substitui a privativa de liberdade não superior a quatro anos.","pode consistir em prestação de outra natureza, se houver aceitação do beneficiário."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - JE TJPE/TJ PE/2011 • TEC 121478","source":"FCC - JE TJPE/TJ PE/2011","subject":"Direito Penal - Das Penas Restritivas de Direitos (arts. 43 a 48 e 54 a 57 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/121478","year":2011,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2152409","sourceQuestionId":"2152409","t":"pen-m06","moduleId":"pen-m06","q":"Sobre a pena de multa, é correto afirmar que","o":["deverá ser calculada após a recuperação do réu, se prevista em abstrato como pena cumulada com a de prisão, em caso de reconhecimento da inimputabilidade na sentença.","consiste no pagamento ao fundo judiciário ou à vítima do delito de certa quantia fixada na sentença, atualizada, em caso de execução, pelos índices de correção monetária.","deve ser paga dentro do prazo de 10 dias da publicação da sentença, permitido o pagamento em parcelas a pedido do condenado.","poderá ser descontada do vencimento ou salário do condenado quando aplicada cumulativamente com a pena privativa de liberdade, nos limites mínimo de um décimo e máximo da quarta parte da remuneração.","a quantia fixada será de, no mínimo, 10 e, no máximo, 360 dias-multa, entre um trigésimo do maior salário mínimo vigente e 5 vezes esse salário, valor total que poderá ser aumentado até o décuplo diante da situação econômica do condenado."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - AJ (TJ CE)/TJ CE/Judiciária/\"Sem Especialidade\"/2022 • TEC 2152409","source":"FCC - AJ (TJ CE)/TJ CE/Judiciária/\"Sem Especialidade\"/2022","subject":"Direito Penal - Da Pena de Multa (arts. 49 a 52 e 58 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2152409","year":2022,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2230543","sourceQuestionId":"2230543","t":"pen-m06","moduleId":"pen-m06","q":"As penas de multa","o":["deverão ser pagas dentro de um ano depois de transitada em julgado a sentença.","podem substituir as penas privativas de liberdade iguais ou inferiores a um ano.","são aplicadas distinta e integralmente no concurso de crimes.","são extintas se sobrevém ao condenado doença mental.","prescrevem em um ano quando a multa for a única cominada ou aplicada."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - DP MT/DPE MT/2022 • TEC 2230543","source":"FCC - DP MT/DPE MT/2022","subject":"Direito Penal - Da Pena de Multa (arts. 49 a 52 e 58 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2230543","year":2022,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1769149","sourceQuestionId":"1769149","t":"pen-m06","moduleId":"pen-m06","q":"A pena de multa","o":["consiste no pagamento de indenização à vítima e é calculada em dias-multa.","só pode ser convertida em pena privativa de liberdade se comprovado que o condenado tem condições de pagá-la, mas não o faz, garantido o devido processo legal.","deve ser aplicada cumulativamente à pena privativa de liberdade, vedada sua aplicação isoladamente.","constitui dívida de valor e deve ser cobrada pela Fazenda Pública, conforme entendimento do Supremo Tribunal Federal.","pode ser cobrada mediante desconto no vencimento ou salário do condenado."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - DP RR/DPE RR/2021 • TEC 1769149","source":"FCC - DP RR/DPE RR/2021","subject":"Direito Penal - Da Pena de Multa (arts. 49 a 52 e 58 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1769149","year":2021,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-285698","sourceQuestionId":"285698","t":"pen-m06","moduleId":"pen-m06","q":"O critério judicial legalmente estabelecido para a fixação da pena pecuniária, na Parte Geral do Código Penal, vincula o juiz à observância, preponderantemente quanto","o":["aos danos sociais provocados pelo crime.","à situação econômica do réu.","à culpabilidade, aos antecedentes, à conduta social, à personalidade do agente e aos motivos, às circunstâncias e consequências do crime.","à culpabilidade, aos antecedentes, à conduta social, à personalidade do agente e ao prejuízo sofrido pela vítima.","às consequências do crime para a vítima."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - JE TJSC/TJ SC/2015 • TEC 285698","source":"FCC - JE TJSC/TJ SC/2015","subject":"Direito Penal - Da Pena de Multa (arts. 49 a 52 e 58 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/285698","year":2015,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-291991","sourceQuestionId":"291991","t":"pen-m06","moduleId":"pen-m06","q":"A pena de multa","o":["prescreve em três anos, quando for a única cominada ou aplicada.","pode substituir, ainda que isoladamente, a pena privativa de liberdade nos casos de violência doméstica e familiar contra a mulher.","é fixada em salários mínimos, considerada a situação econômica do réu.","pode substituir pena privativa de liberdade e ser aplicada em conjunto com restritiva de direitos, nacondenação superior a 1 (um) ano, se presentes os requisitos legais.","obsta a concessão do sursis, se a única aplicada em condenação anterior."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - JE TJRR/TJ RR/2015 • TEC 291991","source":"FCC - JE TJRR/TJ RR/2015","subject":"Direito Penal - Da Pena de Multa (arts. 49 a 52 e 58 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/291991","year":2015,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-373607","sourceQuestionId":"373607","t":"pen-m06","moduleId":"pen-m06","q":"A pena de multa,","o":["obsta a suspensão condicional da pena, ainda que a única aplicada em condenação anterior.","não pode substituir pena privativa de liberdade inferior a um ano, se reincidente o condenado.","deve receber o mesmo acréscimo imposto à pena privativa de liberdade no caso de concurso formal perfeito de infrações.","não pode substituir isoladamente pena privativa de liberdade, nos casos de violência doméstica e familiar contra a mulher, apenas se condenado o agente pelo crime de lesão corporal.","prescreve em três anos se aplicada cumulativamente com pena privativa de liberdade de dez meses de reclusão."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - JE TJPI/TJ PI/2015 • TEC 373607","source":"FCC - JE TJPI/TJ PI/2015","subject":"Direito Penal - Da Pena de Multa (arts. 49 a 52 e 58 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/373607","year":2015,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-217149","sourceQuestionId":"217149","t":"pen-m06","moduleId":"pen-m06","q":"Tratando-se de crime único, praticado sob conduta também única, e considerando o valor do salário mínimo de R$ 724,00, a pena de multa máxima que pode ser fixada com base nos critérios da parte geral do Código Penal é de","o":["R$ 7.240,00.","R$ 260.640,00.","R$ 1.303.200,00.","R$ 3.909.600,00.","R$ 39.096.000,00."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 6: Penas: espécies e cominação.","r":"FCC - DP PB/DPE PB/2014 • TEC 217149","source":"FCC - DP PB/DPE PB/2014","subject":"Direito Penal - Da Pena de Multa (arts. 49 a 52 e 58 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/217149","year":2014,"caderno":2,"classificationReason":"Espécie ou cominação de pena expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1736883","sourceQuestionId":"1736883","t":"pen-m07","moduleId":"pen-m07","q":"A ação penal é pública condicionada","o":["no crime contra a honra de servidor público em razão do exercício de suas funções, admitindo-se, porém, a legitimidade concorrente do ofendido para oferecimento de queixa.","nos crimes contra a liberdade sexual, se a vítima é maior de quatorze e menor de dezoito anos.","no crime de estelionato, salvo, entre outras situações, se a vítima for maior de sessenta anos.","no crime de dano cometido por motivo egoístico.","no crime de exercício arbitrário das próprias razões, se não há emprego de violência."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - JE TJGO/TJ GO/2021 • TEC 1736883","source":"FCC - JE TJGO/TJ GO/2021","subject":"Direito Penal - Da Ação Penal (arts. 100 a 106 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1736883","year":2021,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1037276","sourceQuestionId":"1037276","t":"pen-m07","moduleId":"pen-m07","q":"A ação penal é","o":["pública condicionada à representação no crime de estupro de vulnerável.","privada no crime de dano qualificado por motivo egoístico.","exclusiva do Ministério Público, embora condicionada à representação do ofendido, por crime contra a honra de servidor público em razão do exercício de suas funções.","privada, em qualquer situação, no crime de exercício arbitrário das próprias razões.","pública condicionada à representação no crime de furto cometido em prejuízo de irmão, legítimo ou ilegítimo, independentemente da idade deste."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - JE TJAL/TJ AL/2019 • TEC 1037276","source":"FCC - JE TJAL/TJ AL/2019","subject":"Direito Penal - Da Ação Penal (arts. 100 a 106 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1037276","year":2019,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-638738","sourceQuestionId":"638738","t":"pen-m07","moduleId":"pen-m07","q":"Segundo a doutrina, é possível conceituar a ação penal como o direito do Estado-acusação ou da vítima de ingressar em juízo, pretendendo a prestação jurisdicional, consistente na aplicação das normas de direito penal ao caso concreto. Sobre a ação penal, a legislação vigente dispõe:","o":["A ação de iniciativa privada pode intentar-se nos crimes de ação pública, se o Ministério Público não oferece denúncia no prazo legal.","A ação de iniciativa privada é promovida exclusivamente mediante denúncia do ofendido.","No caso de morte do ofendido ou de ter sido declarado ausente por decisão judicial, o direito de oferecer queixa ou de prosseguir na ação passa ao Ministério Público.","A ação penal é pública, salvo quando a lei expressamente a declara privativa do Ministro da Justiça.","A ação pública é promovida pelo ofendido, dependendo, quando a lei o exige, de representação do Ministério Público ou de requisição do Ministro da Justiça."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - Ana Leg (ALESE)/ALESE/Apoio Técnico ao Processo Legislativo/Processo Legislativo/2018 • TEC 638738","source":"FCC - Ana Leg (ALESE)/ALESE/Apoio Técnico ao Processo Legislativo/Processo Legislativo/2018","subject":"Direito Penal - Da Ação Penal (arts. 100 a 106 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/638738","year":2018,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-362399","sourceQuestionId":"362399","t":"pen-m07","moduleId":"pen-m07","q":"Nos crimes de licitações, a ação penal é pública incondicionada porque","o":["são crimes que violam os princípios de legalidade, impessoalidade, moralidade, publicidade e eficiência da administração pública.","a licitação destina-se a garantir a observância do princípio constitucional da isonomia, a seleção da proposta mais vantajosa para a Administração e a promoção do desenvolvimento nacional sustentável.","cabe ao ministério público promovê-la independentemente de provocação.","o titular da ação penal somente poderá promovê-la mediante requisição do chefe do poder executivo.","é do interesse público a publicidade dos atos licitatórios."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - Proc (Pref Campinas)/Pref Campinas/2016 • TEC 362399","source":"FCC - Proc (Pref Campinas)/Pref Campinas/2016","subject":"Direito Penal - Da Ação Penal (arts. 100 a 106 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/362399","year":2016,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-400545","sourceQuestionId":"400545","t":"pen-m07","moduleId":"pen-m07","q":"Nas ações penais em que a lei exige a representação do ofendido, a retratação pode ocorrer enquanto NÃO:","o":["oferecida a denúncia.","julgada a ação penal.","concluído o inquérito policial.","oferecida a queixa crime.","pronunciado o acusado."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - TRE (SEFAZ MA)/SEFAZ MA/Arrecadação e Fiscalização de Mercadorias em Trânsito/2016 • TEC 400545","source":"FCC - TRE (SEFAZ MA)/SEFAZ MA/Arrecadação e Fiscalização de Mercadorias em Trânsito/2016","subject":"Direito Penal - Da Ação Penal (arts. 100 a 106 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/400545","year":2016,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-259380","sourceQuestionId":"259380","t":"pen-m07","moduleId":"pen-m07","q":"Seja qual for o crime, quando praticado em detrimento do patrimônio ou interesse da União, Estado e Município, a ação penal será","o":["pública condicionada à requisição do Ministro da Justiça.","privada subsidiária da pública.","pública condicionada à representação da pessoa jurídica de direito público.","privada.","pública."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - Ana (CNMP)/CNMP/Apoio Jurídico/Direito/2015 • TEC 259380","source":"FCC - Ana (CNMP)/CNMP/Apoio Jurídico/Direito/2015","subject":"Direito Penal - Da Ação Penal (arts. 100 a 106 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/259380","year":2015,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-315488","sourceQuestionId":"315488","t":"pen-m07","moduleId":"pen-m07","q":"Manoel, munido por sentimento de vingança após um desentendimento, imputa falsamente a Jorge, Mateus e Ricardo, seus vizinhos, um crime de roubo ocorrido em sua residência no dia 10 de Setembro de 2015, ciente da inocência dos mesmos. Os ofendidos, inconformados, pretendem ajuizar ação penal privada contra Manoel. Contudo, Jorge irá perdoar Manoel e subscrever uma declaração para tanto. Neste caso, consumado o perdão do ofendido Jorge,","o":["os ofendidos Mateus e Ricardo não terão os seus direitos prejudicados e poderão ajuizar ação penal privada contra Manoel.","ele só produzirá efeito se efetivado até a data da citação de Manoel na ação penal privada.","Manoel responderá pelo crime contra os três ofendidos, mas estará isento de pena ao final da ação penal.","o direito dos três ofendidos estará prejudicado e não poderá ser ajuizada ação penal privada por nenhum deles.","ele só produzirá efeito se efetivado até a data do ajuizamento da ação penal privada."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - AJ TRE SE/TRE SE/Judiciária/2015 • TEC 315488","source":"FCC - AJ TRE SE/TRE SE/Judiciária/2015","subject":"Direito Penal - Da Ação Penal (arts. 100 a 106 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/315488","year":2015,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-424275","sourceQuestionId":"424275","t":"pen-m07","moduleId":"pen-m07","q":"Quanto à ação penal, é correto afirmar:","o":["Sempre que promovida pelo ofendido, sua injustificada e demorada inércia processual implica extinção da punibilidade por perempção.","Em regra, ela é pública, mais precisamente condicionada à representação da vítima.","O Ministério Público pode dela desistir mesmo fora das hipóteses de menor potencial ofensivo, desde que condicionada à representação e a vítima retratar-se, tempestivamente, da representação antes oferecida.","A requisição do Ministro da Justiça não obriga o Ministério Público a promovê-la, ainda que assim condicionada.","No entender do Supremo Tribunal Federal, é pública condicionada à representação da vítima nos crimes de lesão corporal contra mulher ocorridos em situação de violência doméstica e familiar."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - JE TJAP/TJ AP/2014 • TEC 424275","source":"FCC - JE TJAP/TJ AP/2014","subject":"Direito Penal - Da Ação Penal (arts. 100 a 106 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/424275","year":2014,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"Lei 15.438/2026: nos crimes praticados no âmbito de violência doméstica e familiar contra a mulher, o prazo decadencial especial passou a 12 meses.","auditStatus":"gabarito-historico-com-alerta-de-atualizacao"},{"id":"fcc-penal-120064","sourceQuestionId":"120064","t":"pen-m07","moduleId":"pen-m07","q":"De regra, a ação penal é","o":["pública condicionada à requisição judicial.","pública condicionada à representação da vítima.","exclusivamente privada.","subsidiária da privada.","pública incondicionada."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - NeR (TJ PE)/TJ PE/Remoção/2013 • TEC 120064","source":"FCC - NeR (TJ PE)/TJ PE/Remoção/2013","subject":"Direito Penal - Da Ação Penal (arts. 100 a 106 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/120064","year":2013,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3940940","sourceQuestionId":"3940940","t":"pen-m07","moduleId":"pen-m07","q":"João, brasileiro nato, praticou no ano de 2018, no território brasileiro, conduta que à época era considerada crime, com pena de 2 a 5 anos de reclusão. No entanto, em 2020, sobreveio lei que reduziu a pena para 1 a 3 anos, mantendo a criminalização. Contudo, em 2022, nova lei revogou integralmente o tipo penal, deixando de considerar a conduta criminosa. Considerando a aplicação da lei penal no tempo, em tese aplica-se a lei","o":["de 2020 apenas para fins de dosimetria, sem afastar a tipicidade penal.","mais grave, por ser a vigente à época do julgamento.","vigente em 2018, em razão do princípio do tempus regit actum.","de 2020, pelo fato de ser intermediária e mais benéfica, mantendo-se a condenação.","de 2022, operando-se a abolitio criminis, com extinção da punibilidade."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - TLegis (ALMS)/ALMS/Polícia Legislativa/2026 • TEC 3940940","source":"FCC - TLegis (ALMS)/ALMS/Polícia Legislativa/2026","subject":"Direito Penal - Causas de Extinção da Punibilidade (arts. 107 e 120 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3940940","year":2026,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3023474","sourceQuestionId":"3023474","t":"pen-m07","moduleId":"pen-m07","q":"Maria e José são vizinhos, na cidade de Campo Grande/MS. e desafetos. No bairro onde residem começaram a ocorrer diversos furtos de veículos e de residências. Maria, com o escopo de causar danos ao seu vizinho José, imputou-lhe falsamente a autoria dos referidos furtos em comparsaria com outros indivíduos, não só perante a vizinhança como também em suas redes sociais. Inconformado com a falsa imputação, José ajuizou queixa-crime contra Maria, que foi recebida pelo juízo competente, após o cumprimento de todas as formalidades. Designada audiência de instrução, após regular Intimação de todas as partes envolvidas na ação penal, o querelante José e seu advogado não compareceram ao ato e nem justificaram a ausência. Maria, então, por meio de seu advogado, poderá apresentar ao Magistrado pedido de extinção da punibilidade com base","o":["na decadência.","na renúncia ao direito de queixa.","no perdão do ofendido.","na perempção.","no perdão judicial."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - TJ TRF3/TRF 3/Administrativa/\"Sem Especialidade\"/2024 • TEC 3023474","source":"FCC - TJ TRF3/TRF 3/Administrativa/\"Sem Especialidade\"/2024","subject":"Direito Penal - Causas de Extinção da Punibilidade (arts. 107 e 120 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3023474","year":2024,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2712878","sourceQuestionId":"2712878","t":"pen-m07","moduleId":"pen-m07","q":"A anistia, a graça o indulto são causas","o":["excludentes da ilicitude.","excludentes da culpabilidade.","suspensivas da prescrição.","interruptivas da prescrição.","extintivas da punibilidade."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - Ana JD (DPE AM)/DPE AM/Ciências Jurídicas/2023 • TEC 2712878","source":"FCC - Ana JD (DPE AM)/DPE AM/Ciências Jurídicas/2023","subject":"Direito Penal - Causas de Extinção da Punibilidade (arts. 107 e 120 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2712878","year":2023,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1981294","sourceQuestionId":"1981294","t":"pen-m07","moduleId":"pen-m07","q":"O perdão judicial é aplicável ao delito de","o":["homicídio culposo, exceto se o crime tiver sido praticado na direção de veículo automotor, conforme jurisprudência do Superior Tribunal de Justiça.","estelionato, praticado na modalidade culposa, conforme previsto expressamente no Código Penal.","receptação, praticado na modalidade dolosa ou culposa, conforme previsto expressamente no Código Penal.","guarda doméstica de espécie silvestre, exceto se considerada ameaçada de extinção, conforme previsto na Lei no 9.605/1998 (Lei dos crimes ambientais).","lesão corporal de natureza leve, praticado na modalidade dolosa ou culposa, conforme previsto expressamente no Código Penal."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - DP PB/DPE PB/2022 • TEC 1981294","source":"FCC - DP PB/DPE PB/2022","subject":"Direito Penal - Causas de Extinção da Punibilidade (arts. 107 e 120 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1981294","year":2022,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1981328","sourceQuestionId":"1981328","t":"pen-m07","moduleId":"pen-m07","q":"É possível a extinção da punibilidade pela retratação do agente no crime de","o":["injúria, desde que feita cabalmente e pelo mesmo meio de sua prática.","incitação ao crime, até o oferecimento da denúncia.","lesão corporal submetido à Lei Maria da Penha (Lei no 11.340/2006), desde que feita em juízo até o recebimento da denúncia.","falso testemunho, antes da sentença no processo em que ocorreu o ilícito.","desacato, se feita de forma espontânea até o trânsito em julgado."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - DP PB/DPE PB/2022 • TEC 1981328","source":"FCC - DP PB/DPE PB/2022","subject":"Direito Penal - Causas de Extinção da Punibilidade (arts. 107 e 120 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1981328","year":2022,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-592928","sourceQuestionId":"592928","t":"pen-m07","moduleId":"pen-m07","q":"A extinção da punibilidade pode ser compreendida como sendo a perda do direito do Estado de impor sanção penal ao autor de fato típico e ilícito. É possível, assim, encontrar hipóteses de extinção da punibilidade no Código Penal, bem como nas legislações extravagantes. Acerca do tema, é correto afirmar:","o":["As causas de extinção de punibilidade sempre se comunicam aos coautores e partícipes, em razão de se tratar de matéria de ordem pública.","A sentença que conceder perdão judicial não será considerada para efeitos de reincidência.","A anistia, graça ou indulto não são hipóteses de extinção da punibilidade, por serem atos concedidos pelo chefe do Poder Executivo, e não pelo Judiciário.","Nos crimes conexos, a extinção da punibilidade de um deles impede, quanto aos outros, a agravação da pena resultante da conexão.","Na hipótese de abolitio criminis (abolição do crime.) permanece a reincidência como efeito secundário da infração penal."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - Proc (PGE TO)/PGE TO/2018 • TEC 592928","source":"FCC - Proc (PGE TO)/PGE TO/2018","subject":"Direito Penal - Causas de Extinção da Punibilidade (arts. 107 e 120 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/592928","year":2018,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-660040","sourceQuestionId":"660040","t":"pen-m07","moduleId":"pen-m07","q":"Extingue-se a punibilidade do agente","o":["pela retroatividade da lei que diminui a pena do crime.","pela superveniência de doença mental do autor do ilícito.","pela reparação do dano ou restituição da coisa objeto do ilícito, em qualquer crime.","pelo perdão do ofendido, em qualquer crime.","pelo perdão judicial, nos casos previstos em lei."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - AFT I (Pref São Luís)/Pref São Luís/Abrangência Geral/2018 • TEC 660040","source":"FCC - AFT I (Pref São Luís)/Pref São Luís/Abrangência Geral/2018","subject":"Direito Penal - Causas de Extinção da Punibilidade (arts. 107 e 120 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/660040","year":2018,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-583814","sourceQuestionId":"583814","t":"pen-m07","moduleId":"pen-m07","q":"Praticado o ilícito penal por um indivíduo culpável, surge para o Estado o direito de aplicar a sanção penal prevista na lei incriminadora. Contudo, o direito de punir não é absoluto, sendo possível que ocorra alguma causa extintiva de punibilidade, impedindo que o Estado imponha a sanção ao agente. Diante disso, com fundamento no que dispõe o Código Penal sobre a extinção de punibilidade, é corretor afirmar:","o":["No caso de evadir-se o condenado ou de revogar-se o livramento condicional, a prescrição é regulada pelo máximo da pena privativa de liberdade cominada ao crime.","Nos crimes conexos, a extinção da punibilidade de um deles impede, quanto aos outros, a agravação da pena resultante da conexão.","A prescrição, depois da sentença condenatória com trânsito em julgado para a acusação ou depois de improvido seu recurso, regula-se pela pena aplicada, podendo, ainda, ter por termo inicial data anterior à da denúncia ou queixa.","Aplicam-se às penas restritivas de direito os mesmos prazos prescricionais previstos para as privativas de liberdade.","A prescrição da pena de multa ocorrerá em 2 anos quando a multa for alternativa ou cumulativamente cominada ou cumulativamente aplicada."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - AJ TRF5/TRF 5/Judiciária/Oficial de Justiça Avaliador Federal/2017 • TEC 583814","source":"FCC - AJ TRF5/TRF 5/Judiciária/Oficial de Justiça Avaliador Federal/2017","subject":"Direito Penal - Causas de Extinção da Punibilidade (arts. 107 e 120 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/583814","year":2017,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-264790","sourceQuestionId":"264790","t":"pen-m07","moduleId":"pen-m07","q":"No tocante à ação penal, é correto afirmar que","o":["implica renúncia tácita do direito de queixa o fato de receber o ofendido a indenização do dano causado pelo crime.","admissível a renúncia tácita, mas o perdão do ofendido deve ser expresso.","a renúncia constitui causa de extinção da punibilidade relativa às ações penais privadas e públicas condicionadas.","concedido o perdão por um dos ofendidos, não prejudica o direito dos outros.","admissível o perdão do ofendido mesmo depois que passa em julgado a sentença condenatória."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - JE TJGO/TJ GO/2015 • TEC 264790","source":"FCC - JE TJGO/TJ GO/2015","subject":"Direito Penal - Causas de Extinção da Punibilidade (arts. 107 e 120 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/264790","year":2015,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-271866","sourceQuestionId":"271866","t":"pen-m07","moduleId":"pen-m07","q":"O perdão do ofendido","o":["é admissível mesmo depois que passa em julgado a sentença condenatória.","prejudica o direito dos outros, se concedido por um dos ofendidos.","não aproveita a todos, se concedido apenas a um dos querelados.","só é admissível se expresso.","exige aceitação do querelado para produzir efeito."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - JT TRT6/TRT 6/2015 • TEC 271866","source":"FCC - JT TRT6/TRT 6/2015","subject":"Direito Penal - Causas de Extinção da Punibilidade (arts. 107 e 120 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/271866","year":2015,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-291995","sourceQuestionId":"291995","t":"pen-m07","moduleId":"pen-m07","q":"Constituem causas de extinção da punibilidade que se relacionam com a ação penal pública condicionada","o":["a perempção e o perdão do ofendido.","a decadência e a perempção.","o perdão do ofendido e a composição homologada dos danos civis nos juizado especial criminal.","a decadência e o perdão do ofendido.","a composição homologada dos danos civis no juizado especial criminal e a decadência."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - JE TJRR/TJ RR/2015 • TEC 291995","source":"FCC - JE TJRR/TJ RR/2015","subject":"Direito Penal - Causas de Extinção da Punibilidade (arts. 107 e 120 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/291995","year":2015,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-299597","sourceQuestionId":"299597","t":"pen-m07","moduleId":"pen-m07","q":"O perdão judicial tem natureza jurídica de","o":["causa de exclusão de culpabilidade.","causa extintiva da punibilidade.","efeito da sentença penal.","desistência voluntária.","efeito civil da sentença penal."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - Aud Sub Cons (TCE-AM)/TCE AM/2015 • TEC 299597","source":"FCC - Aud Sub Cons (TCE-AM)/TCE AM/2015","subject":"Direito Penal - Causas de Extinção da Punibilidade (arts. 107 e 120 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/299597","year":2015,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-171878","sourceQuestionId":"171878","t":"pen-m07","moduleId":"pen-m07","q":"NÃO é causa extintiva da punibilidade:","o":["prescrição, após o lançamento do tributo.","morte do agente, após definitiva a condenação.","retratação do querelado, na calúnia contra os mortos.","perempção, na ação penal privada subsidiária da pública.","perdão judicial, na apropriação indébita previdenciária."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - AJ TRF3/TRF 3/Judiciária/Oficial de Justiça Avaliador Federal/2014 • TEC 171878","source":"FCC - AJ TRF3/TRF 3/Judiciária/Oficial de Justiça Avaliador Federal/2014","subject":"Direito Penal - Causas de Extinção da Punibilidade (arts. 107 e 120 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/171878","year":2014,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-218043","sourceQuestionId":"218043","t":"pen-m07","moduleId":"pen-m07","q":"Na lei penal brasileira, NÃO é causa extintiva da punibilidade","o":["a retratação cabal do querelado, antes da sentença, na calúnia e na difamação.","o perdão judicial, no peculato mediante erro de outrem.","a reparação integral do dano, no peculato culposo, quando precedente à sentença irrecorrível.","a retratação ou declaração da verdade, antes da sentença no processo em que ocorreu o ilícito, no falso testemunho ou falsa perícia.","a declaração, confissão e o pagamento espontâneos das contribuições, valores, importâncias e informações devidas à previdência social, na forma definida em lei ou regulamento, antes do início da ação fiscal, na apropriação indébita previdenciária."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - AFTE (SEFAZ PE)/SEFAZ PE/2014 • TEC 218043","source":"FCC - AFTE (SEFAZ PE)/SEFAZ PE/2014","subject":"Direito Penal - Causas de Extinção da Punibilidade (arts. 107 e 120 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/218043","year":2014,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-121269","sourceQuestionId":"121269","t":"pen-m07","moduleId":"pen-m07","q":"Em relação às causas de extinção da punibilidade, correto afirmar que","o":["não a configuram a concessão de indulto parcial ou comutação, de competência privativa do Presidente da República.","cabível o perdão judicial no caso de qualquer infração penal.","a concessão de anistia é de competência privativa do Presidente da República, excluindo o crime e fazendo desaparecer suas consequências penais.","a concessão de indulto faz com que o beneficiado retorne à condição de primário.","não são previstas, em qualquer situação, para casos de reparação do dano pelo agente."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - JE TJPE/TJ PE/2013 • TEC 121269","source":"FCC - JE TJPE/TJ PE/2013","subject":"Direito Penal - Causas de Extinção da Punibilidade (arts. 107 e 120 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/121269","year":2013,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-184077","sourceQuestionId":"184077","t":"pen-m07","moduleId":"pen-m07","q":"Constituem causas de extinção da punibilidade relacionadas exclusivamente aos crimes de ação penal privada","o":["o perdão do ofendido e o perdão judicial.","a decadência e o perdão do ofendido.","a renúncia e a perempção.","a perempção e o perdão judicial.","a renúncia e a decadência."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - JT TRT6/TRT 6/2013 • TEC 184077","source":"FCC - JT TRT6/TRT 6/2013","subject":"Direito Penal - Causas de Extinção da Punibilidade (arts. 107 e 120 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/184077","year":2013,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1567487","sourceQuestionId":"1567487","t":"pen-m07","moduleId":"pen-m07","q":"Constituem causas de extinção da punibilidade exclusivamente relacionadas a crimes de ação penal privada:","o":["o perdão aceito e a perempção.","a renúncia ao direito de queixa e a retratação do agente.","a decadência e o perdão judicial.","a retratação do agente e a perempção.","o perdão aceito e a decadência."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - Prom Jus (MPE AP)/MPE AP/2012 • TEC 1567487","source":"FCC - Prom Jus (MPE AP)/MPE AP/2012","subject":"Direito Penal - Causas de Extinção da Punibilidade (arts. 107 e 120 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1567487","year":2012,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-23675","sourceQuestionId":"23675","t":"pen-m07","moduleId":"pen-m07","q":"O perdão do ofendido","o":["não é admissível fora do processo.","não aproveita aos demais querelados, se concedido.","é admissível mesmo depois de passar em julgado a sentença condenatória.","não produz efeito, se o querelado o recusa.","prejudica o direito dos outros, se concedido apenas por um dos ofendidos."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - Proc (MP TCE-SP)/TCE SP/2011 • TEC 23675","source":"FCC - Proc (MP TCE-SP)/TCE SP/2011","subject":"Direito Penal - Causas de Extinção da Punibilidade (arts. 107 e 120 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/23675","year":2011,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-98033","sourceQuestionId":"98033","t":"pen-m07","moduleId":"pen-m07","q":"De acordo com o Código Penal NÃO é causa de extinção da punibilidade a","o":["reparação do dano posterior à sentença irrecorrível no crime de peculato culposo.","morte do agente.","anistia.","prescrição.","retroatividade de lei que não mais considera o fato como criminoso."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - AJ TRE AP/TRE AP/Judiciária/2011 • TEC 98033","source":"FCC - AJ TRE AP/TRE AP/Judiciária/2011","subject":"Direito Penal - Causas de Extinção da Punibilidade (arts. 107 e 120 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/98033","year":2011,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-121480","sourceQuestionId":"121480","t":"pen-m07","moduleId":"pen-m07","q":"Em matéria de extinção da punibilidade, é possível assegurar que","o":["as causas de aumento ou de diminuição, com exceção do concurso material, do concurso formal e do crime continuado, devem ser computadas no prazo prescricional.","as medidas de segurança não se sujeitam à prescrição.","a reincidência não interfere na prescrição da pretensão executória.","a prescrição admite interrupção, mas não suspensão.","é admissível pela prescrição da pretensão punitiva com fundamento em pena hipotética, independentemente da existência ou sorte do processo penal, segundo súmula do Superior Tribunal de Justiça."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - JE TJPE/TJ PE/2011 • TEC 121480","source":"FCC - JE TJPE/TJ PE/2011","subject":"Direito Penal - Causas de Extinção da Punibilidade (arts. 107 e 120 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/121480","year":2011,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-713362","sourceQuestionId":"713362","t":"pen-m07","moduleId":"pen-m07","q":"O rol do art. 107 do Código Penal (extinção de punibilidade) é exemplificativo. Há outras causas previstas na Parte Especial e leis penais especiais, entre elas:","o":["o ressarcimento do dano no peculato culposo; o pagamento do tributo antes do recebimento da denúncia nos crimes de sonegação fiscal e a retratação no crime de falso testemunho.","a retratação no crime de falso testemunho; o aborto quando não há outro meio de salvar a vida da gestante e o furto contra cônjuge, na constância do casamento.","o furto e o roubo impróprio contra cônjuge na constância do casamento; o ressarcimento do dano no peculato culposo e o pagamento do tributo antes do recebimento da denúncia no crime de sonegação fiscal.","o ressarcimento integral do prejuízo no caso de estelionato; a retratação no crime de falso testemunho e a retratação do querelado na calúnia ou difamação.","em todos os casos de crimes cometidos sem violência ou grave ameaça contra a pessoa em que haja reparação do dano."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - Prom Jus (MPE CE)/MPE CE/2011 • TEC 713362","source":"FCC - Prom Jus (MPE CE)/MPE CE/2011","subject":"Direito Penal - Causas de Extinção da Punibilidade (arts. 107 e 120 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/713362","year":2011,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3937815","sourceQuestionId":"3937815","t":"pen-m07","moduleId":"pen-m07","q":"Vicente, réu primário e com 20 anos, foi denunciado pela prática do crime de furto simples. Ao final, foi condenado de forma definitiva ao pagamento de 10 dias- multa, pois incurso no delito previsto no artigo 155, § 2º, do Código Penal. Os fatos datam de 22/01/2018. A denúncia foi recebida em 28/04/2020. O processo foi regularmente suspenso, nos termos do artigo 366, do Código de Processo Penal em 29/05/2023. Regularmente citado, o curso do processo foi retomado em 03/08/2023. A sentença condenatória data de 24/08/2023, sendo certificado o trânsito em julgado para as partes na mesma data. No caso, ocorreu a prescrição da pretensão punitiva","o":["pela pena em concreto em 27/04/2021.","pela pena em abstrato em 21/07/2019.","retroativa em 21/01/2019.","pela pena em concreto em 27/04/2022.","pela pena em concreto em 23/08/2024."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - DP MA/DPE MA/2026 • TEC 3937815","source":"FCC - DP MA/DPE MA/2026","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3937815","year":2026,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3355372","sourceQuestionId":"3355372","t":"pen-m07","moduleId":"pen-m07","q":"A prescrição","o":["tem seus prazos reduzidos pela metade quando o agente era, ao tempo do crime, menor de vinte e um anos, ou, na data da sentença, maior de sessenta anos.","da pena de multa ocorrerá em dois anos quando aplicada cumulativamente com a pena privativa de liberdade.","é regulada pelo tempo que resta da pena no caso de evasão do condenado durante o seu cumprimento.","tem seu curso interrompido pelo oferecimento da denúncia ou queixa.","no caso de concurso de crimes, tem seu prazo aumentado em um terço."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - AnaDP (DPE SP)/DPE SP/2025 • TEC 3355372","source":"FCC - AnaDP (DPE SP)/DPE SP/2025","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3355372","year":2025,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3467601","sourceQuestionId":"3467601","t":"pen-m07","moduleId":"pen-m07","q":"Giovana, primária e de bons antecedentes, foi denunciada pela prática dos delitos previstos no artigo 129, caput, do Código Penal (pena: 3 meses a 1 ano), e no artigo 140, § 3º, do Código Penal (pena: 1 ano a 3 anos), em concurso material, pois no dia 24 de novembro de 2018, durante a comemoração do seu aniversário de 20 anos, teria agredido e ofendido sua vizinha, chamando-a de \"aleljadinha\". A denúncia foi recebida em 15 de janeiro de 2019, mas a ré não foi localizada para ser citada, tendo sido determinada sua citação por edital. Não tendo a ré comparecido nem constituído advogado, o juiz determinou a suspensão do processo em 17 de março de 2019, nos termos do artigo 366, do Código de Processo Penal. Em 20 de janeiro de 2024 a ré compareceu ao cartório e foi citada do processo, tendo o juiz na mesma data revogado a suspensão. Designada audiência de instrução para 25 de maio de 2025, o Defensor Público poderia alegar prescrição da pretensão punitiva pela:","o":["pena em perspectiva, ocorrida em julho de 2020 em relação ao delito de lesão leve, e prescrição da pretensão punitiva pela pena em perspectiva, ocorrida em janeiro de 2021 em relação ao delito de injúria.","pena em concreto, ocorrida em março de 2022 em relação ao delito de lesão leve, e a prescrição da pretensão punitiva pela pena em perspectiva, ocorrida em março de 2025 em relação ao delito de injúria.","pena em perspectiva, ocorrida em janeiro de 2021 em relação ao delito de lesão leve, e prescrição da pretensão punitiva pela pena em perspectiva, ocorrida em janeiro de 2022 em relação ao delito de injúria.","pena máxima em abstrato, ocorrida em março de 2021 em relação ao delito de lesão leve, e prescrição da pretensão punitiva pela pena máxima em abstrato, ocorrida em março de 2023 em relação ao delito de injúria.","pena máxima em abstrato, ocorrida em janeiro de 2023 em relação ao delito de lesão leve, e prescrição da pretensão punitiva pela pena em perspectiva, ocorrida em janeiro de 2025 em relação ao delito de injúria."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - DP AM/DPE AM/2025 • TEC 3467601","source":"FCC - DP AM/DPE AM/2025","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3467601","year":2025,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3542588","sourceQuestionId":"3542588","t":"pen-m07","moduleId":"pen-m07","q":"Considere as seguintes situações hipotéticas: I . Patrick, primário, com 20 anos de idade, cometeu um crime de roubo em 12 de abril de 2019. Denúncia apresentada pelo Ministério Público Federal recebida em 18 de julho de 2019. Sentença publicada em 30 de setembro de 2023, que o condenou a cumprir pena de 04 anos de reclusão e 10 dias-multa. II . Moisés, primário, cometeu um crime de furto qualificado em 10 de outubro de 2019. Denúncia apresentada pelo Ministério Público Federal recebida em 11 de novembro de 2023. Sentença publicada em 20 de junho de 2025, que o condenou a cumprir pena de 02 anos de reclusão e 10 dias-multa. Na data da sentença, Moisés tinha 72 anos de idade. III . Ronald, tecnicamente primário, com 38 anos de idade, cometeu crime de falsidade ideológica em 02 de setembro de 2021. A denúncia apresentada pelo Ministério Público Federal foi recebida em 02 de fevereiro de 2022. Sentença publicada em 20 de maio de 2025, que o condenou a cumprir pena de 01 ano de reclusão e 10 dias-multa. Nos termos preconizados pelo Código Penal, com base nas penas aplicadas para cada um dos casos acima apresentados, e operado o trânsito em julgado, o prazo prescricional está consumado, devendo o Magistrado competente extinguir a punibilidade de:","o":["Patrick e Moisés, apenas.","Patrick, apenas.","Moisés e Ronald , apenas.","Patrick e Ronald, apenas.","Moisés, apenas."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - AJ TRF4/TRF 4/Judiciária/Oficial de Justiça Avaliador Federal/2025 • TEC 3542588","source":"FCC - AJ TRF4/TRF 4/Judiciária/Oficial de Justiça Avaliador Federal/2025","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3542588","year":2025,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3561324","sourceQuestionId":"3561324","t":"pen-m07","moduleId":"pen-m07","q":"Analise os seguintes casos hipotéticos: I. Julio, com 19 anos de idade, foi preso em flagrante pelo crime de furto no dia 13 de outubro de 2020. Posteriormente, a denúncia apresentada pelo Ministério Público foi recebida pela Justiça no dia 15 de fevereiro de 2021. Após a regular instrução do feito, Julio foi condenado pelo Magistrado competente a cumprir pena de 2 anos de reclusão. A sentença foi publicada em 19 de outubro de 2024. II. Marcela, de 25 anos de idade, foi denunciada pelo Ministério Público pelo crime de contratação inidônea, ao admitir à licitação, no dia 2 de fevereiro de 2021, empresa declarada inidônea. A denúncia foi recebida no dia 3 de março de 2024. Após a regular instrução do feito, Marcela foi condenada pelo Magistrado competente a cumprir pena de 1 ano de reclusão. A sentença foi publicada no dia 9 de abril de 2025. III. Samir, de 40 anos de idade, foi denunciado pelo Ministério Público pelo crime de falsidade ideológica cometido no dia 13 de dezembro de 2021. A denúncia foi recebida no dia 11 de abril de 2022. Após a regular instrução do feito, Samir foi condenado pelo Magistrado competente a cumprir pena de 1 ano de reclusão. A sentença foi publicada no dia 14 de junho de 2025. IV. Rinaldo foi denunciado pelo Ministério Público pelo crime de Frustração do caráter competitivo de licitação, cometido no dia 11 de julho de 2019. A denúncia foi recebida no dia 14 de dezembro de 2019. Após a regular instrução do feito, Rinaldo, já com setenta anos de idade, foi condenado a cumprir pena de quatro anos de reclusão. A sentença foi publicada em 1º de fevereiro de 2025. Nos termos preconizados pelo Código Penal, a prescrição da pretensão punitiva estatal restou consumada com base na pena fixada APENAS para:","o":["Marcela e Samir.","Julio e Rinaldo.","Julio, Samir e Rinaldo.","Marcela, Samir e Rinaldo.","Julio, Marcela e Samir."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - AFFE (SEFAZ PI)/SEFAZ PI/Geral/2025 • TEC 3561324","source":"FCC - AFFE (SEFAZ PI)/SEFAZ PI/Geral/2025","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3561324","year":2025,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3563030","sourceQuestionId":"3563030","t":"pen-m07","moduleId":"pen-m07","q":"Thiago, servidor público estadual, foi processado e definitivamente condenado pela prática de crime de peculato (art. 312, caput, do Código Penal) às penas de reclusão de dois anos e dez dias-multa, o unitário no mínimo legal. Os fatos foram praticados em 20/03/2016, a denúncia recebida em 15/05/2020 e a sentença condenatória publicada em 20/07/2022. Thiago completou 70 (setenta) anos de idade em 13/09/2021 . A sentença condenatória transitou em julgado em 28/01/2024. Nesta hipótese:","o":["não ocorreu prescrição, seja da pretensão punitiva ou executória.","ocorreu a prescrição da pretensão punitiva entre a data do recebimento da denúncia e a da publicação da sentença condenatória.","ocorreu a prescrição da pretensão punitiva entre a data dos falos e a do recebimento da denúncia.","ocorreu a prescrição da pretensão punitiva entre a data da publicação da sentença condenatória e seu transito em julgado.","ocorreu a prescrição da pretensão executória após o trânsito em julgado da sentença condenatória."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - AFFE (SEFAZ PI)/SEFAZ PI/Tecnologia da Informação/2025 • TEC 3563030","source":"FCC - AFFE (SEFAZ PI)/SEFAZ PI/Tecnologia da Informação/2025","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3563030","year":2025,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3021813","sourceQuestionId":"3021813","t":"pen-m07","moduleId":"pen-m07","q":"Ronaldo, funcionário público, cometeu crime de prevaricação em 12 de abril de 2018. Após o trâmite do inquérito policial, Ronaldo foi denunciado pelo Ministério Público pelo crime do artigo 319, do Código Penal (prevaricação). A denúncia foi recebida em 19 de maio de 2021. Após a regular instrução do feito, Ronaldo é condenado pelo Magistrado competente ao cumprimento da pena privativa de liberdade de 6 meses de detenção, em regime inicial semiaberto, por sentença publicada no dia 2 de maio de 2023. Na data da sentença, Ronaldo, reincidente em crime doloso, possuía 71 anos de idade. Após o trânsito em julgado da sentença, Ronaldo, por meio de seu advogado, apresenta requerimento de extinção da punibilidade com base na prescrição diante da pena em concreto imposta. Sobre o caso hipotético apresentado, o prazo da prescrição da pretensão punitiva estatal é de:","o":["3 anos, mas o Magistrado não deverá extinguir a punibilidade de Ronaldo, pois o termo inicial da prescrição com base na pena aplicada não pode ter por termo inicial data anterior à da denúncia.","2 anos, e não restou consumado, devendo o feito prosseguir na fase executória.","4 anos, e não restou consumado, devendo o feito prosseguir na fase executória.","3 anos, cabendo ao Magistrado extinguir a punibilidade de Ronaldo com base na prescrição, que se consumou no lapso temporal transcorrido entre a data do crime e a do recebimento da denúncia.","1 ano e 6 meses, cabendo ao Magistrado extinguir a punibilidade de Ronaldo com base na prescrição, que se consumou no lapso temporal transcorrido entre a data do recebimento da denúncia e da publicação da sentença."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - AJ TRF3/TRF 3/Judiciária/\"Sem Especialidade\"/2024 • TEC 3021813","source":"FCC - AJ TRF3/TRF 3/Judiciária/\"Sem Especialidade\"/2024","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3021813","year":2024,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2741054","sourceQuestionId":"2741054","t":"pen-m07","moduleId":"pen-m07","q":"Fernando, com 20 anos de idade à época do fato, foi preso em flagrante em 10 de abril de 2011 pela prática do delito de receptação simples (art. 180, caput, do CP), tendo sido solto por se tratar de indiciado primário acusado de delito cuja pena é de 1 a 4 anos. Recebida a denúncia em 10 de agosto de 2013, foi determinada a citação do réu. Ante a sua não localização, o juiz determinou a citação por edital. Não tendo Fernando comparecido e nem constituído defensor, foi determinada a suspensão do feito em 15 de julho de 2014, nos termos do art. 366 do CPP. Em 15 de abril de 2021, Fernando foi preso por outro processo e foi citado do presente feito, que voltou a correr. Realizada a audiência de instrução, foi publicada sentença em 15 de agosto de 2021, condenando Fernando à pena de um ano de reclusão, no regime aberto. A sentença transitou em julgado para a acusação em 15 de setembro de 2021, tendo a Defesa apelado. Foi negado provimento ao recurso de defesa e a sentença transitou em julgado para ambas as partes em 15 de maio de 2023. Realizada audiência de ingresso no regime aberto em 17 de agosto de 2023, seria possível alegar prescrição da pretensão:","o":["executória com base na pena aplicada em concreto, ocorrida entre a data da publicação da sentença condenatória até a data da audiência em regime aberto.","punitiva intercorrente com base na pena aplicada em concreto, ocorrida entre a data da publicação da sentença condenatória e a data da audiência de ingresso em regime aberto.","punitiva com base na pena máxima cominada em abstrato ao delito, ocorrida no período compreendido entre a data da infração penal e a data da citação pessoal do réu.","punitiva retroativa com base na pena em concreto, ocorrida no período compreendido entre a retomada do cômputo do prazo prescricional e a sentença condenatória.","executória com base na pena em concreto, ocorrida entre a data da retomada do curso do processo e o trânsito em julgado para ambas as partes."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - DP ES/DPE ES/2023 • TEC 2741054","source":"FCC - DP ES/DPE ES/2023","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2741054","year":2023,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1981325","sourceQuestionId":"1981325","t":"pen-m07","moduleId":"pen-m07","q":"A prescrição NÃO corre","o":["com a decisão confirmatória da pronúncia até o julgamento em plenário do Tribunal do Júri.","entre o recebimento da denúncia e a sentença condenatória.","enquanto o agente é processado penalmente no exterior.","durante o cumprimento do acordo de transação penal.","enquanto não cumprido ou não rescindido o acordo de não persecução penal."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - DP PB/DPE PB/2022 • TEC 1981325","source":"FCC - DP PB/DPE PB/2022","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1981325","year":2022,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1994836","sourceQuestionId":"1994836","t":"pen-m07","moduleId":"pen-m07","q":"Nas ações penais de iniciativa privada, a prescrição, depois da sentença condenatória com trânsito em julgado para o querelante ou depois de improvido seu recurso, é calculada pela pena","o":["liquidada no juízo da execução.","aplicada, não podendo ter por termo inicial data anterior à do recebimento da queixa.","máxima cominada, não podendo ter por termo inicial data posterior àquela em que o crime se consumou.","aplicada, não podendo ter por termo inicial data posterior à da sentença condenatória.","aplicada, não podendo ter por termo inicial data anterior à da queixa."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - Prom Jus (MPE PE)/MPE PE/2022 • TEC 1994836","source":"FCC - Prom Jus (MPE PE)/MPE PE/2022","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1994836","year":2022,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2038221","sourceQuestionId":"2038221","t":"pen-m07","moduleId":"pen-m07","q":"João Ricardo, nascido em 10/01/2002, foi condenado a uma pena total de 02 (dois) anos e 04 (quatro) meses de reclusão pela prática de crimes de furto qualificado, nos termos do art. 155, § 4º, inc. III, c/c art. 71, caput, do Código Penal, em razão de ter subtraído três veículos no mês de fevereiro de 2021. Na primeira fase da dosimetria da pena, o magistrado considerou a primariedade e os bons antecedentes do réu e fixou a pena-base no mínimo legal em dois anos. Em seguida, na última fase, reconheceu a continuidade delitiva e exasperou a pena em 1/6. Não houve recurso das partes e a sentença penal condenatória transitou em julgado em 12 de dezembro de 2021. Considerando a situação do réu João Ricardo, o prazo da prescrição da pretensão executória é de","o":["12 anos.","02 anos.","04 anos.","08 anos.","03 anos."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - DP CE/DPE CE/2022 • TEC 2038221","source":"FCC - DP CE/DPE CE/2022","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2038221","year":2022,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2038236","sourceQuestionId":"2038236","t":"pen-m07","moduleId":"pen-m07","q":"A prescrição NÃO corre enquanto","o":["o agente responde a processo criminal no exterior.","não cumprida a transação penal.","pendentes embargos de declaração e embargos infringentes e de nulidade.","está foragido o condenado.","durar a suspensão condicional do processo."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - DP CE/DPE CE/2022 • TEC 2038236","source":"FCC - DP CE/DPE CE/2022","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2038236","year":2022,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2152407","sourceQuestionId":"2152407","t":"pen-m07","moduleId":"pen-m07","q":"A prescrição depois de transitar em julgado a sentença condenatória","o":["pode ter como termo inicial prazo anterior à denúncia.","regula-se pela pena máxima do delito.","regula-se pela pena da sentença, desconsiderando-se a reincidência.","considera o total da pena aplicada na sentença, inclusive com a causa de aumento do crime continuado.","sofre aumento de um terço se o réu for reincidente."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - AJ (TJ CE)/TJ CE/Judiciária/\"Sem Especialidade\"/2022 • TEC 2152407","source":"FCC - AJ (TJ CE)/TJ CE/Judiciária/\"Sem Especialidade\"/2022","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2152407","year":2022,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2163329","sourceQuestionId":"2163329","t":"pen-m07","moduleId":"pen-m07","q":"Atenção: A questão refere-se a Direito Penal. De acordo com o que estabelece o Código Penal e o entendimento dos Tribunais Superiores acerca da extinção da punibilidade:","o":["Aplicam-se às penas restritivas de direito os mesmos prazos de prescrição previstos para as penas privativas de liberdade.","A prescrição, depois de transitar em julgado a sentença condenatória, regula-se pelo máximo da pena privativa de liberdade cominada ao crime, que aumenta de um terço, se o condenado é reincidente.","A prescrição, antes de transitar em julgado a sentença final, começa a correr nos crimes permanentes, do dia em que se iniciou a prática criminosa.","São reduzidos de metade os prazos de prescrição quando o criminoso era, ao tempo do crime, menor de dezoito anos, ou, na data da sentença, maior de sessenta e cinco anos.","A sentença que, embora tenha concedido o perdão judicial, ainda será considerada para efeitos de reincidência."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - ARE (SEFAZ AP)/SEFAZ AP/2022 • TEC 2163329","source":"FCC - ARE (SEFAZ AP)/SEFAZ AP/2022","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2163329","year":2022,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2163601","sourceQuestionId":"2163601","t":"pen-m07","moduleId":"pen-m07","q":"Atenção: As questão refere-se a Direito Penal. Acerca da extinção da punibilidade, o Código Penal e o entendimento dos Tribunais Superiores estabelece:","o":["No caso de evadir-se o condenado ou de revogar-se o livramento condicional, a prescrição é regulada pelo tempo que resta da pena.","O curso da prescrição interrompe-se enquanto não resolvida, em outro processo, questão de que dependa o reconhecimento da existência do crime.","Antes de passar em julgado a sentença final, a prescrição não corre enquanto o agente cumpre pena por outro delito em território nacional ou no exterior.","A prescrição da pena de multa ocorrerá no mesmo prazo estabelecido para prescrição da pena privativa de liberdade quando a multa for a única cominada ou aplicada.","No caso de concurso de crimes, a extinção da punibilidade incidirá sobre o total da pena aplicada em conjunto."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - FRE (SEFAZ AP)/SEFAZ AP/2022 • TEC 2163601","source":"FCC - FRE (SEFAZ AP)/SEFAZ AP/2022","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2163601","year":2022,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2230561","sourceQuestionId":"2230561","t":"pen-m07","moduleId":"pen-m07","q":"Sobre a prescrição, é correto afirmar:","o":["A reincidência aumenta o prazo da prescrição da pretensão punitiva em terça parte.","O curso do prazo prescricional é interrompido pela decisão que aplica a medida de segurança.","A prescrição da pretensão punitiva não corre durante o tempo em que o agente está preso por outro motivo.","No crime de falsidade ideológica a prescrição da pretensão punitiva se inicia quando da consumação do delito.","A prescrição da prestação pecuniária ocorrerá em dois anos quando for a única pena aplicada."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - DP MT/DPE MT/2022 • TEC 2230561","source":"FCC - DP MT/DPE MT/2022","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2230561","year":2022,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1684621","sourceQuestionId":"1684621","t":"pen-m07","moduleId":"pen-m07","q":"Sobre a prescrição, é correto afirmar:","o":["Nos crimes ambientais, a prescrição corre pela metade quando é reconhecida a baixa escolaridade do acusado.","Os recursos aos Tribunais Superiores somente suspendem o prazo prescricional quando inadmissíveis.","Após a chamada Lei Anticrime, o prazo prescricional em caso de crime hediondos ou equiparado não se submete a redução em razão da idade.","Em caso de tentativa, o termo inicial da prescrição da pretensão punitiva é o do início da atividade criminosa.","O prazo prescricional do Código Penal é reduzido em um sexto caso seja reconhecida uma atenuante na aplicação da pena."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - DP BA/DPE BA/2021 • TEC 1684621","source":"FCC - DP BA/DPE BA/2021","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1684621","year":2021,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1752348","sourceQuestionId":"1752348","t":"pen-m07","moduleId":"pen-m07","q":"Constitui causa interruptiva da prescrição","o":["decretação da prisão temporária.","continuação do cumprimento da pena.","interposição de embargos de declaração quando inadmissíveis.","decisão de impronúncia.","cumprimento de pena no exterior."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - DP GO/DPE GO/2021 • TEC 1752348","source":"FCC - DP GO/DPE GO/2021","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1752348","year":2021,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1769159","sourceQuestionId":"1769159","t":"pen-m07","moduleId":"pen-m07","q":"A prescrição","o":["em caso de crime continuado regula-se pela pena imposta na sentença, não se computando o acréscimo decorrente da continuação.","da pretensão punitiva corre sempre que pendentes embargos de declaração ou recursos aos Tribunais Superiores.","em caso de revogação do livramento condicional é regulada por todo o tempo da pena.","da pretensão executória não recebe influência da reincidência em sua contagem de prazo.","é incabível em caso de medida de segurança em razão da periculosidade do agente."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - DP RR/DPE RR/2021 • TEC 1769159","source":"FCC - DP RR/DPE RR/2021","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1769159","year":2021,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1797037","sourceQuestionId":"1797037","t":"pen-m07","moduleId":"pen-m07","q":"São efeitos da reincidência a I da prescrição e o aumento do prazo da prescrição da pretensão II . Completam, correta e respectivamente, as lacunas I ...... ...... e II:","o":["suspensão − punitiva e executória","interrupção − executória","interrupção − punitiva","suspensão − punitiva","interrupção − punitiva e executória"],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - DP SC/DPE SC/2021 • TEC 1797037","source":"FCC - DP SC/DPE SC/2021","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1797037","year":2021,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1147340","sourceQuestionId":"1147340","t":"pen-m07","moduleId":"pen-m07","q":"No tocante à prescrição, correto afirmar que","o":["cometido o homicídio qualificado para ocultar outro crime, a prescrição deste impede a qualificação daquele.","os crimes mais leves prescrevem com os mais graves, se cometidos em concurso de delitos.","é regulada pelo total da pena nos casos de evasão do condenado ou de revogação do livramento condicional.","não se aplicam às penas restritivas de direito os mesmos prazos previstos para as privativas de liberdade.","a sua ocorrência em relação ao crime de furto não alcança a receptação que o tinha como pressuposto."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - JE TJMS/TJ MS/2020 • TEC 1147340","source":"FCC - JE TJMS/TJ MS/2020","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1147340","year":2020,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-943344","sourceQuestionId":"943344","t":"pen-m07","moduleId":"pen-m07","q":"Considere as seguintes situações hipotéticas: Reginaldo, com 19 anos de idade, cometeu um crime de apropriação indébita, com pena prevista de 1 a 4 anos de reclusão e multa; Manoel, com 22 anos de idade, cometeu crime de desacato contra um policial rodoviário federal, com pena prevista de 6 meses a 2 anos de detenção; Moisés, com 70 anos de idade, cometeu crime de contrabando, com pena prevista de 1 a 5 anos de reclusão. Nos casos acima apontados, a prescrição da pretensão punitiva estatal, antes do trânsito em julgado da sentença final, verifica-se, respectivamente, no prazo de","o":["8 anos, 4 anos e 6 anos","8 anos, 4 anos e 12 anos.","4 anos, 3 anos e 12 anos.","8 anos, 3 anos e 12 anos.","4 anos, 4 anos e 6 anos."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - AJ TRF4/TRF 4/Judiciária/Oficial de Justiça Avaliador Federal/2019 • TEC 943344","source":"FCC - AJ TRF4/TRF 4/Judiciária/Oficial de Justiça Avaliador Federal/2019","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/943344","year":2019,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-943394","sourceQuestionId":"943394","t":"pen-m07","moduleId":"pen-m07","q":"Sobre a extinção da punibilidade, nos termos preconizados pelo Código Penal, é correto afirmar:","o":["A prescrição da pena de multa ocorrerá no prazo de 2 anos quando ela for cumulativamente cominada com a pena privativa de liberdade.","Nos crimes conexos, a extinção da punibilidade de um deles não impede, quanto aos outros, a agravação da pena resultante da conexão.","A sentença que conceder o perdão judicial será considerada para fins de reincidência.","São reduzidos pela metade os prazos de prescrição quando o criminoso era, ao tempo do crime, menor de 21 (vinte e um) anos ou, na data da sentença, maior de 60 (sessenta) anos.","A prescrição, depois da sentença condenatória com trânsito em julgado para a acusação, regula-se pela pena aplicada, e poderá ter por termo inicial data anterior à da denúncia ou queixa."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - AJ TRF4/TRF 4/Judiciária/\"Sem Especialidade\"/2019 • TEC 943394","source":"FCC - AJ TRF4/TRF 4/Judiciária/\"Sem Especialidade\"/2019","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/943394","year":2019,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1072745","sourceQuestionId":"1072745","t":"pen-m07","moduleId":"pen-m07","q":"Com relação à prescrição da pretensão executória,","o":["ocorre com o transcurso do lapso prescricional da execução do crime até o recebimento da denúncia.","no caso de evasão do condenado, regula-se pelo tempo que resta da pena.","tem como causa suspensiva a sentença de pronúncia.","é contada em dobro no caso de crimes hediondos.","começa a correr do dia em que cessou a atividade criminosa, no caso de tentativa."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - Ana JD (DPE AM)/DPE AM/Ciências Jurídicas/2019 • TEC 1072745","source":"FCC - Ana JD (DPE AM)/DPE AM/Ciências Jurídicas/2019","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1072745","year":2019,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-605426","sourceQuestionId":"605426","t":"pen-m07","moduleId":"pen-m07","q":"Sobre a extinção da punibilidade:","o":["O perdão judicial independe de lei, pois é realizado por meio de Decreto Presidencial.","No caso de concurso de crimes, o cálculo da prescrição incide sobre a somatória das penas.","Ao contrário da renúncia ao direito de queixa, a decadência é causa de extinção da punibilidade.","O prazo de prescrição é reduzido pela metade quando o agente for maior de setenta anos na data da sentença.","Em caso de revogação do livramento condicional, a prescrição da pretensão executória é regulada pelo total da pena imposta."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - Ana JD (DPE AM)/DPE AM/Ciências Jurídicas/2018 • TEC 605426","source":"FCC - Ana JD (DPE AM)/DPE AM/Ciências Jurídicas/2018","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/605426","year":2018,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-662237","sourceQuestionId":"662237","t":"pen-m07","moduleId":"pen-m07","q":"Sobre a prescrição, é correto afirmar que","o":["em caso de revogação do livramento condicional, a prescrição é regulada pelo resto de pena a cumprir.","o prazo mínimo de prescrição na legislação penal brasileira é de 3 anos.","a decisão confirmatória de pronúncia nos crimes submetidos ao Tribunal do Júri é causa suspensiva da prescrição.","em caso de concurso material de crimes, o cálculo prescricional incide sobre a soma das penas.","o crime de tráfico de drogas por ser equiparado a hediondo é imprescritível."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - DP AM/DPE AM/2018 • TEC 662237","source":"FCC - DP AM/DPE AM/2018","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/662237","year":2018,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-682663","sourceQuestionId":"682663","t":"pen-m07","moduleId":"pen-m07","q":"A prescrição","o":["da pretensão punitiva não corre enquanto o agente cumpre pena no estrangeiro.","tem seu prazo reduzido em um terço quando o criminoso era menor de 21 anos na data do fato.","tem seu curso interrompido pelo oferecimento da denúncia ou queixa.","no concurso de crimes incide sobre a pena somada de todos eles.","da pena de multa ocorrerá em 3 anos quando for a única aplicada ou cominada."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 7: Ação penal, punibilidade, extinção e prescrição.","r":"FCC - Proc Leg (CL DF)/CL DF/2018 • TEC 682663","source":"FCC - Proc Leg (CL DF)/CL DF/2018","subject":"Direito Penal - Da Prescrição (arts. 108 a 119 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/682663","year":2018,"caderno":3,"classificationReason":"Ação penal, punibilidade, extinção ou prescrição expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"});
